$content = "package com.attendance.server.models`n`nimport org.jetbrains.exposed.sql.Table`nimport org.jetbrains.exposed.sql.javatime.timestamp`n`nobject AttendanceSessions : Table(`"attendance_sessions`") {`n    val id = uuid(`"id`").autoGenerate()`n    val classId = uuid(`"class_id`").references(Classes.id)`n    val teacherId = uuid(`"teacher_id`").references(Users.id)`n    val startedAt = timestamp(`"started_at`")`n    val checkIntervalMinutes = integer(`"check_interval_minutes`")`n    val minSuccessfulChecks = integer(`"min_successful_checks`")`n    val sessionStatus = varchar(`"session_status`", 50).default(`"ACTIVE`")`n    val endedAt = timestamp(`"ended_at`").nullable()`n    val reviewDeadline = timestamp(`"review_deadline`").nullable()`n    val sessionSecret = varchar(`"session_secret`", 255).nullable()`n    override val primaryKey = PrimaryKey(id)`n}`n`nobject AttendanceRecords : Table(`"attendance_records`") {`n    val id = uuid(`"id`").autoGenerate()`n    val sessionId = uuid(`"session_id`").references(AttendanceSessions.id)`n    val studentId = uuid(`"student_id`").references(Users.id)`n    val successfulChecks = integer(`"successful_checks`")`n    val lastDetectedAt = timestamp(`"last_detected_at`")`n    val faceVerified = bool(`"face_verified`").default(true)`n    val initialStatus = varchar(`"initial_status`", 50).default(`"PENDING`")`n    val overrideStatus = varchar(`"override_status`", 50).nullable()`n    val finalStatus = varchar(`"final_status`", 50).nullable()`n    val createdAt = timestamp(`"created_at`")`n    val updatedAt = timestamp(`"updated_at`").nullable()`n    val hasCheckoutScan = bool(`"has_checkout_scan`").default(false)`n    val reviewReason = varchar(`"review_reason`", 255).nullable()`n    override val primaryKey = PrimaryKey(id)`n}"`nSet-Content "backend/src/main/kotlin/com/attendance/server/models/AttendanceModels.kt" $content
